"use client";

import { createContext, useContext, useCallback, useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { ArrowDown, ArrowUp, ArrowDownUp, ArrowLeft, ArrowRight, Check, ChevronDown, Circle, Code2, Copy, ExternalLink, Eye, Info, Pencil, Plus, Search, Trash2 } from "lucide-react";
import { defaultEmailPreferences, defaultFooterHtml, defaultOptInHtml, defaultUnsubscribeHtml, emailPreferenceTabs, validateEmailPreferences, type EmailPreferenceTab, type EmailPreferences, type HtmlPreference, type TextTheme, type ThemePadding } from "@/lib/email-preferences";
import { registerUnsavedNavigation } from "@/lib/unsaved-navigation";
import { htmlToPlainText } from "@/lib/email-liquid";
import styles from "./email-preferences.module.css";

const docs = "https://www.braze.com/docs/user_guide/administer/global/workspace_settings/email_preferences";
const themeSections = ["Basic Styling", "Title Styling", "Paragraph Styling", "List Styling", "Fallback Fonts", "Button Styling", "Icon Block Styling", "Email Template Width", "Content Block Width"];
const pageSections = ["Custom footer", "Custom unsubscribe page", "Custom opt-in page"];
const slug = (value: string) => value.toLowerCase().replaceAll(" ", "-");
const fonts = ["Open Sans", "Arial", "Helvetica", "Georgia", "Tahoma", "Verdana", "Times New Roman", "Courier New"];

function Learn({ href = docs, children = "Learn more" }: { href?: string; children?: ReactNode }) { return <a href={href} target="_blank" rel="noreferrer">{children} <ExternalLink size={15}/></a>; }
const EmailPreferencesReadOnly = createContext(false);
function Heading({ children, editing, large = false, readOnly = false }: { children: ReactNode; editing: boolean; large?: boolean; readOnly?: boolean }) { const isReadOnly = useContext(EmailPreferencesReadOnly) || readOnly; return <div className={styles.heading}><h2 className={large ? styles.largeHeading : undefined}>{children}</h2>{!editing && <span className={styles.viewOnly} title={isReadOnly ? "You do not have permission to edit these settings." : "Settings are currently in viewing mode. Use Edit settings to make changes."}><Eye size={15}/>{isReadOnly ? " View only" : " Viewing"}</span>}</div>; }

function Toggle({ label, help, checked, onChange, disabled }: { label: string; help?: ReactNode; checked: boolean; onChange: (value: boolean) => void; disabled: boolean }) {
  return <div className={styles.toggleRow}><label><input type="checkbox" role="switch" checked={checked} disabled={disabled} onChange={event => onChange(event.target.checked)}/><span className={styles.switch} aria-hidden="true"/><span>{label}</span></label>{help && <p>{help}</p>}</div>;
}
function ValueField({ label, value, onChange, editing, type = "text", options, min = 0, max = 2000, ariaLabel }: { label: string; ariaLabel?: string; value: string | number; onChange: (value: string) => void; editing: boolean; type?: string; options?: string[]; min?: number; max?: number }) {
  return <label className={styles.valueField}><span>{label}</span>{editing ? options ? <select aria-label={ariaLabel} value={String(value)} onChange={event => onChange(event.target.value)}>{options.map(option => <option key={option} value={option}>{option}</option>)}</select> : <input aria-label={ariaLabel} type={type} min={min} max={max} value={value} onChange={event => onChange(event.target.value)}/> : <span className={styles.readValue}>{options ? ({ltr:"Left to right",rtl:"Right to left",left:"Left",center:"Center",right:"Right",normal:"Normal",bold:"Bold",ul:"Bulleted List",ol:"Numbered List",default:"Default",disc:"Disc",circle:"Circle",square:"Square",decimal:"Decimal"}[String(value)] ?? value) : value}</span>}</label>;
}
function ColorField({ label, value, editing, onChange, ariaLabel }: { label: string; ariaLabel?: string; value: string; editing: boolean; onChange: (value: string) => void }) {
  return <label className={styles.valueField}><span>{label}</span><span className={styles.colorValue}><input type="color" aria-label={ariaLabel ?? label} disabled={!editing} value={value} onChange={event => onChange(event.target.value)}/>{editing ? <input aria-label={`${ariaLabel ?? label} hex`} value={value.toUpperCase()} maxLength={7} onChange={event => onChange(event.target.value)}/> : <span>{value.toUpperCase()}</span>}</span></label>;
}

export default function EmailPreferencesWorkspace({ notify }: { notify: (message: string) => void }) {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const router = useRouter();
  const tab = emailPreferenceTabs.find(([key]) => pathname.split("/").includes(key))?.[0] ?? "sending_configuration";
  const [data, setData] = useState<EmailPreferences>(defaultEmailPreferences);
  const [saved, setSaved] = useState<EmailPreferences>(defaultEmailPreferences);
  const [updatedAt, setUpdatedAt] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [canEdit, setCanEdit] = useState(false);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);
  const [loadError, setLoadError] = useState("");
  const [discardTarget, setDiscardTarget] = useState<EmailPreferenceTab | "cancel" | "external" | null>(null);
  const pendingNavigation = useRef<(() => void) | null>(null);
  const dirty = JSON.stringify(data) !== JSON.stringify(saved);
  const load = useCallback(async () => {
    setLoading(true); setLoadError("");
    try {
      const response = await fetch("/api/email-preferences");
      if (!response.ok) throw new Error("Email preferences could not be loaded. Try again.");
      const result = await response.json();
      setData(result.data); setSaved(result.data); setUpdatedAt(result.updatedAt); setCanEdit(result.permissions?.canEdit !== false);
      try { const draft = JSON.parse(sessionStorage.getItem("email-preferences-draft") || "null"); if (result.permissions?.canEdit !== false && draft?.data?.sending && draft.data.pages && draft.data.editor) { setData(draft.data); setUpdatedAt(draft.updatedAt); setEditing(true); if (draft.updatedAt !== result.updatedAt) setErrors(["Your unsaved draft was restored. Workspace settings changed elsewhere; review the latest settings before saving."]); } } catch {}
    } catch (error) { setLoadError(error instanceof Error ? error.message : "Unable to load settings."); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);
  useEffect(() => {
    const guard = (event: BeforeUnloadEvent) => { if (dirty) { event.preventDefault(); event.returnValue = ""; } };
    window.addEventListener("beforeunload", guard);
    return () => window.removeEventListener("beforeunload", guard);
  }, [dirty]);
  useEffect(() => {
    if (loading) return;
    if (dirty) sessionStorage.setItem("email-preferences-draft", JSON.stringify({ data, updatedAt }));
    else sessionStorage.removeItem("email-preferences-draft");
  }, [data, dirty, loading, updatedAt]);
  useLayoutEffect(() => {
    if (!dirty) return;
    const defer = (action: () => void) => { pendingNavigation.current = action; setDiscardTarget("external"); };
    const unregister = registerUnsavedNavigation(defer);
    const anchor = (event: MouseEvent) => { const link = (event.target as Element)?.closest<HTMLAnchorElement>("a[href]"); if (!link || link.target === "_blank" || event.metaKey || event.ctrlKey) return; if (link.origin === location.origin && link.href !== location.href) { event.preventDefault(); event.stopPropagation(); defer(() => router.push(link.href)); } };
    let leaving = false;
    const currentUrl = location.href, currentState = history.state;
    const pop = (event: PopStateEvent) => { if (leaving) return; event.stopImmediatePropagation(); const targetUrl = location.href; history.pushState(currentState, "", currentUrl); router.replace(currentUrl); defer(() => { leaving = true; router.replace(targetUrl); }); };
    const navigation = (window as unknown as { navigation?: EventTarget }).navigation;
    const onNavigate = (event: Event) => { const next = event as Event & { canIntercept?: boolean; navigationType?: string; destination?: { url: string } }; if (leaving || !next.canIntercept || next.navigationType !== "traverse" || !next.destination) return; event.preventDefault(); const destination = next.destination.url; defer(() => { leaving = true; router.push(destination); }); };
    navigation?.addEventListener("navigate", onNavigate);
    document.addEventListener("click", anchor, true); window.addEventListener("popstate", pop, true);
    return () => { navigation?.removeEventListener("navigate", onNavigate); unregister(); document.removeEventListener("click", anchor, true); window.removeEventListener("popstate", pop, true); };
  }, [dirty, router]);
  const navigate = (next: EmailPreferenceTab) => {
    const match = pathname.match(/\/email_settings\/(?:[^/]+\/)?([a-f0-9]{24})/);
    const workspace = match?.[1] ?? "6ad0b98fe4b4110085216601";
    router.push(`/app_settings/app_settings/email_settings/${next}/${workspace}?${searchParams.toString() || "locale=en"}`);
    window.scrollTo({ top: 0 });
  };
  const switchTab = (next: EmailPreferenceTab) => { if (tab === next) return; if (dirty) setDiscardTarget(next); else { setEditing(false); setErrors([]); navigate(next); } };
  const cancel = () => { if (dirty) setDiscardTarget("cancel"); else { setEditing(false); setErrors([]); } };
  const save = async () => {
    if (!canEdit) return;
    const issues = validateEmailPreferences(data);
    setErrors(issues);
    if (issues.length || saving) return;
    setSaving(true);
    try {
      const response = await fetch("/api/email-preferences", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ data, expectedUpdatedAt: updatedAt }) });
      const result = await response.json();
      if (!response.ok) { setErrors(result.errors ?? [result.error ?? "Unable to save. Your changes have been kept."]); return; }
      setData(result.data); setSaved(result.data); setUpdatedAt(result.updatedAt); setEditing(false); notify("Email preferences saved.");
    } catch { setErrors(["Unable to save email preferences. Your changes have been kept. Try again."]); }
    finally { setSaving(false); }
  };
  const patchSending = (patch: Partial<EmailPreferences["sending"]>) => setData(current => ({ ...current, sending: { ...current.sending, ...patch } }));
  const patchEditor = (patch: Partial<EmailPreferences["editor"]>) => setData(current => ({ ...current, editor: { ...current.editor, ...patch } }));

  return <EmailPreferencesReadOnly.Provider value={!canEdit}><section className={styles.workspace} aria-label="Email Preferences">
    <nav className={styles.tabs} role="tablist" aria-label="Email preferences sections">{emailPreferenceTabs.map(([key, label]) => <button key={key} role="tab" tabIndex={tab === key ? 0 : -1} onKeyDown={event => { const keys = ["ArrowRight", "ArrowLeft", "Home", "End"]; if (!keys.includes(event.key)) return; event.preventDefault(); const buttons = Array.from(event.currentTarget.parentElement!.querySelectorAll<HTMLButtonElement>('[role="tab"]')); const index = buttons.indexOf(event.currentTarget); const next = event.key === "Home" ? 0 : event.key === "End" ? buttons.length - 1 : (index + (event.key === "ArrowRight" ? 1 : -1) + buttons.length) % buttons.length; buttons.forEach((button, i) => button.tabIndex = i === next ? 0 : -1); buttons[next].focus(); }} id={`email-tab-${key}`} aria-selected={tab === key} aria-controls="email-settings-panel" onClick={() => switchTab(key)}>{label}</button>)}</nav>
    {loadError ? <div className={styles.error} role="alert">{loadError}<button onClick={() => void load()}>Try again</button></div> : loading ? <p className={styles.loading} role="status">Loading email preferences…</p> : <>
      {tab !== "ip_warming" && canEdit && <div className={styles.actionBar}>{editing ? <><span>{dirty ? "Unsaved changes" : "Editing email preferences"}</span><button className={styles.secondary} disabled={saving} onClick={cancel}>Cancel</button><button className={styles.primary} disabled={saving || !dirty} onClick={() => void save()}><Check size={15}/>{saving ? "Saving…" : "Save changes"}</button></> : <button className={styles.editAction} onClick={() => setEditing(true)}><Pencil size={14}/> Edit settings</button>}</div>}
      {!!errors.length && <div className={styles.error} role="alert"><b>Changes could not be saved</b><ul>{errors.map(error => <li key={error}>{error}</li>)}</ul></div>}
      <div role="tabpanel" id="email-settings-panel" aria-labelledby={`email-tab-${tab}`}>
        {tab === "sending_configuration" && <SendingSettings data={data.sending} editing={editing} patch={patchSending}/>}
        {tab === "subscription_pages_and_footers" && <SubscriptionSettings data={data.pages} editing={editing} patch={(key, value) => setData(current => ({ ...current, pages: { ...current.pages, [key]: value } }))}/>}
        {tab === "drag_and_drop_email" && <EditorSettings data={data.editor} editing={editing} patch={patchEditor}/>}
        {tab === "link_aliasing" && <LinkAliases editing={editing} notify={notify}/>}
        {tab === "bot_filtering" && <BotSettings value={data.removeBotClicks} editing={editing} onChange={value => setData(current => ({ ...current, removeBotClicks: value }))}/>}
        {tab === "ip_warming" && <IpWarming/>}
      </div>
    </>}
    <footer className={styles.footer}><span>© Braze 2026</span><span><a href="https://braze.statuspage.io/" target="_blank" rel="noreferrer">Status</a><a href="https://www.braze.com/terms" target="_blank" rel="noreferrer">Terms</a><a href="https://www.braze.com/privacy" target="_blank" rel="noreferrer">Privacy Policy</a></span></footer>
    {discardTarget && <div className={styles.dialogBackdrop}><section className={styles.dialog} role="dialog" aria-modal="true" aria-label="Discard unsaved changes?"><h2>Discard unsaved changes?</h2><p>Your changes have not been saved.</p><div><button className={styles.secondary} onClick={() => setDiscardTarget(null)}>Keep editing</button><button className={styles.primary} onClick={() => { setData(saved); setEditing(false); setErrors([]); if (discardTarget === "external") { sessionStorage.removeItem("email-preferences-draft"); const action = pendingNavigation.current; pendingNavigation.current = null; window.setTimeout(() => action?.(), 0); } else if (discardTarget !== "cancel") navigate(discardTarget); setDiscardTarget(null); }}>Discard changes</button></div></section></div>}
  </section></EmailPreferencesReadOnly.Provider>;
}

function SendingSettings({ data, editing, patch }: { data: EmailPreferences["sending"]; editing: boolean; patch: (patch: Partial<EmailPreferences["sending"]>) => void }) {
  const field = (label: string, value: string, onChange: (value: string) => void) => <ValueField label={label} value={value} editing={editing} onChange={onChange}/>;
  const addresses = (kind: "replyTo" | "bcc") => {
    const title = kind === "bcc" ? "BCC" : "Reply-To";
    const defaultKey = kind === "bcc" ? "defaultBccId" : "defaultReplyToId";
    return <div className={styles.addressList}>{data[kind].map((entry, index) => <div className={styles.addressRow} key={entry.id}>{field(`${title} address ${index + 1}`, entry.address, value => patch({ [kind]: data[kind].map(item => item.id === entry.id ? { ...item, address: value } : item) }))}{editing ? <><button type="button" className={styles.linkButton} onClick={() => patch({ [defaultKey]: entry.id })}>{data[defaultKey] === entry.id ? "Default" : "Make Default"}</button><button aria-label={`Remove ${title} address ${index + 1}`} className={styles.iconButton} onClick={() => patch({ [kind]: data[kind].filter(item => item.id !== entry.id), ...(data[defaultKey] === entry.id ? { [defaultKey]: "" } : {}) })}><Trash2 size={17}/></button></> : data[defaultKey] === entry.id && <small>Default</small>}</div>)}{editing && <button className={styles.linkButton} onClick={() => patch({ [kind]: [...data[kind], { id: crypto.randomUUID(), address: "" }] })}><Plus size={16}/> Add {title} address</button>}</div>;
  };
  return <div className={styles.sending}>
    <section className={styles.card}>
      <Heading editing={editing}>Outbound Email Settings</Heading><p>Set a default name and email address used when Braze sends emails to your users</p><hr/>
      <h3>Display Name Address</h3><p>Emails to your users can be delivered with the display names and addresses added here</p>
      <div className={styles.senderList}>{data.senders.map((sender, index) => <div className={styles.senderRow} key={sender.id}>
        {field("From Display Name", sender.displayName, value => patch({ senders: data.senders.map(item => item.id === sender.id ? { ...item, displayName: value } : item) }))}
        {field("Local Part", sender.localPart, value => patch({ senders: data.senders.map(item => item.id === sender.id ? { ...item, localPart: value } : item) }))}<span className={styles.at}>@</span>
        {editing ? <div className={styles.domainFields}>{field("Domain", sender.domain, value => patch({ senders: data.senders.map(item => item.id === sender.id ? { ...item, domain: value } : item) }))}{field("IP Pool (Sending Provider)", sender.ipPool, value => patch({ senders: data.senders.map(item => item.id === sender.id ? { ...item, ipPool: value } : item) }))}</div> : <ValueField label="Domain | IP Pool (Sending Provider)" value={`${sender.domain} | ${sender.ipPool}`} editing={false} onChange={() => {}}/>}
        {editing && <button className={styles.iconButton} disabled={data.senders.length === 1} aria-label={`Remove sender ${index + 1}`} onClick={() => patch({ senders: data.senders.filter(item => item.id !== sender.id) })}><Trash2 size={17}/></button>}
      </div>)}{editing && <button className={styles.linkButton} onClick={() => patch({ senders: [...data.senders, { id: crypto.randomUUID(), displayName: "", localPart: "", domain: data.senders[0]?.domain ?? "", ipPool: data.senders[0]?.ipPool ?? "" }] })}><Plus size={16}/> Add display name address</button>}</div>
      <h3>Reply-To Address</h3><p>Emails to your users can be sent with these reply-to addresses</p>{addresses("replyTo")}
      <Toggle label="Require use of addresses listed above for the From and Reply-To fields" checked={data.requireListedAddresses} disabled={!editing} onChange={value => patch({ requireListedAddresses: value })}/><hr/>
      <h3>BCC Address</h3><p>Emails to your users can be sent with these addresses in the BCC field. When you add a BCC address to an email, Braze sends one message to each user and one message to the BCC address. This will double your billable emails.</p>{addresses("bcc")}
      <Toggle label="Require a BCC address for all your email campaigns" checked={data.requireBcc} disabled={!editing} onChange={value => patch({ requireBcc: value })}/>
    </section>
    <section className={styles.card}><h2>Open Tracking Pixel</h2><p>Move invisible open tracking pixel to the <b>top of email</b> HTML</p><p className={styles.muted}>By default, the invisible open tracking pixel is located at the bottom of the email HTML. <Learn href={`${docs}#open-tracking-pixel`}/></p><Toggle label="Move for SparkPost" checked={data.movePixelToTop} disabled={!editing} onChange={value => patch({ movePixelToTop: value })}/></section>
    <section className={styles.card}><h2>Email Unsubscribe Header</h2><p>Automatically display a one-click unsubscribe button for the emails you send from this workspace. You can override the global header for specific emails from the <b>Sending Info</b> tab of the email editor</p>
      <Toggle label="Include a one-click list-unsubscribe (mailto and HTTP) email header for emails sent to subscribed or opted-in users" checked={data.unsubscribeHeader} disabled={!editing} onChange={value => patch({ unsubscribeHeader: value })} help={<>Allows email providers to include an unsubscribe button for emails. <Learn href={`${docs}#list-unsubscribe-header`}/></>}/><hr/>
      <div className={styles.radios}><label><input type="radio" name="unsubscribe-mode" disabled={!editing || !data.unsubscribeHeader} checked={data.unsubscribeMode === "global"} onChange={() => patch({ unsubscribeMode: "global" })}/><span>Unsubscribe globally from all emails (default)<small>Set the user&apos;s global email subscription state to Unsubscribed with the standard Braze URL and mail-to</small></span></label><label><input type="radio" name="unsubscribe-mode" disabled={!editing || !data.unsubscribeHeader} checked={data.unsubscribeMode === "custom"} onChange={() => patch({ unsubscribeMode: "custom" })}/><span>Custom list-unsubscribe header<small>Process unsubscribes via API</small></span></label></div>
      {data.unsubscribeMode === "custom" && <div className={styles.customHeader}>{field("One-click unsubscribe URL", data.unsubscribeUrl, value => patch({ unsubscribeUrl: value }))}{field("Mailto (Optional)", data.unsubscribeMailto, value => patch({ unsubscribeMailto: value }))}</div>}
    </section>
    <section className={styles.card}><h2>Test and Seed Email Subject Lines</h2><Toggle label={'Include "[TEST]" and "[SEED]" in test and seed email subject lines'} checked={data.prefixTestSubject} disabled={!editing} onChange={value => patch({ prefixTestSubject: value })} help={'If the subject line contains "test" or "seed", some inbox providers may block the email or mark it as spam'}/></section>
    <section className={styles.card}><h2>CSS Inlining</h2><Toggle label="CSS inlining on new emails" checked={data.inlineCss} disabled={!editing} onChange={value => patch({ inlineCss: value })} help={<>CSS inlining can improve email rendering for some email clients. This setting will not impact any of your existing email messages or templates. You can override this setting when composing email messages. <Learn href="https://www.braze.com/docs/user_guide/channels/email/html_editor/css_inline"/></>}/></section>
    <section className={styles.card}><h2>Resubscribe Users</h2><Toggle label="Resubscribe users when they update their email" checked={data.resubscribe} disabled={!editing} onChange={value => patch({ resubscribe: value })} help={<>Previously unsubscribed users are automatically resubscribed when they change their email address to one that isn&apos;t on Braze&apos;s unsubscribe list. <Learn href={`${docs}#resubscribe-users-when-their-email-changes`}/></>}/></section>
  </div>;
}

function SectionNavigation({ sections, scrollRef }: { sections: string[]; scrollRef: React.RefObject<HTMLDivElement | null> }) {
  const [active, setActive] = useState("");
  return <nav className={styles.sectionNav} aria-label="Settings sections">{sections.map(label => <button className={active === label ? styles.activeSection : undefined} key={label} onClick={() => { setActive(label); const node = scrollRef.current?.querySelector<HTMLElement>(`#${slug(label)}`); node?.scrollIntoView({ block: "start", behavior: "smooth" }); }}>{label}</button>)}</nav>;
}
function SubscriptionSettings({ data, editing, patch }: { data: EmailPreferences["pages"]; editing: boolean; patch: (key: keyof EmailPreferences["pages"], value: HtmlPreference) => void }) {
  const scrollRef = useRef<HTMLDivElement | null>(null);
  return <div className={styles.splitCard}><SectionNavigation sections={pageSections} scrollRef={scrollRef}/><div ref={scrollRef} className={styles.sectionContent}>{(["footer", "unsubscribe", "optIn"] as const).map((key, index) => <HtmlSection key={key} title={pageSections[index]} kind={key} value={data[key]} editing={editing} onChange={value => patch(key, value)}/>)}</div></div>;
}
function HtmlSection({ title, kind, value, editing, onChange }: { title: string; kind: "footer" | "unsubscribe" | "optIn"; value: HtmlPreference; editing: boolean; onChange: (value: HtmlPreference) => void }) {
  const [code, setCode] = useState(true);
  const [plain, setPlain] = useState(false);
  const [userId, setUserId] = useState("");
  const [users, setUsers] = useState<Array<{ id: string; email: string }>>([]);
  const [preview, setPreview] = useState("");
  const [previewError, setPreviewError] = useState("");
  const [previewing, setPreviewing] = useState(false);
  const [previewUser, setPreviewUser] = useState("");
  const [share, setShare] = useState("");
  useEffect(() => { void fetch("/api/users?limit=100").then(r => r.json()).then(result => setUsers(result.data ?? [])).catch(() => setPreviewError("Preview users could not be loaded.")); }, []);
  const renderPreview = useCallback(async () => { setPreviewing(true); setPreviewError(""); try { const response = await fetch("/api/email-preferences/preview", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ kind, html: value.html, userId }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); setPreview(result.html); setPreviewUser(result.user.email); setCode(false); setPlain(false); setShare(""); } catch (error) { setPreviewError(error instanceof Error ? error.message : "Preview failed."); } finally { setPreviewing(false); } }, [kind, value.html, userId]);
  const sharePreview = async () => { try { const response = await fetch("/api/email-preferences/share", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ html: preview }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); setShare(new URL(result.url, location.origin).href); } catch { setPreviewError("Could not create a preview link. Try again."); } };
  const [copied, setCopied] = useState(false);
  const [copyError, setCopyError] = useState("");
  const defaultHtml = kind === "footer" ? defaultFooterHtml : kind === "unsubscribe" ? defaultUnsubscribeHtml : defaultOptInHtml;
  return <section className={styles.htmlSection} id={slug(title)}>
    <Heading editing={editing}>{title}</Heading>
    <p>{kind === "footer" ? <>A custom footer is HTML that is added to the end of your email. It is referenced by using a Liquid snippet in the email message. Footers must include an unsubscribe URL and physical mailing address. Learn more about email best practices <Learn href={kind === "footer" ? "https://www.braze.com/docs/en/user_guide/message_building_by_channel/email/custom_email_footer" : "https://www.braze.com/docs/en/user_guide/message_building_by_channel/email/managing_user_subscriptions/"}>here</Learn></> : <>You can customize the {kind === "optIn" ? "opt-in" : "unsubscribe"} page your users see by inputting your own html. Learn more about the best practices for email list management <Learn href="https://www.braze.com/docs/en/user_guide/message_building_by_channel/email/managing_user_subscriptions/">here</Learn></>}</p>
    <Toggle label={`Enable ${title.toLowerCase()}`} checked={value.enabled} disabled={!editing} onChange={enabled => onChange({ ...value, enabled })}/>
    {value.enabled && <div className={styles.htmlEditor}>
      <div className={styles.codeActions}><span><Code2 size={16}/> HTML Editor</span>{editing && <button className={styles.linkButton} onClick={() => onChange({ ...value, html: defaultHtml })}>Reset to default</button>}</div>
      <p className={styles.muted}>{kind === "footer" ? "Custom footers must be less than 100 KB and include an unsubscribe URL and physical mailing address." : "Custom subscription pages must be less than 750 KB."}</p>
      <div className={styles.previewActions}><button aria-pressed={code} className={code ? styles.selected : ""} onClick={() => { setCode(true); setPlain(false); }}>HTML</button><button aria-pressed={!code} className={!code ? styles.selected : ""} disabled={previewing} onClick={() => void renderPreview()}>Preview</button><button className={styles.copyButton} onClick={() => { void navigator.clipboard.writeText(kind === "footer" ? "{{${email_footer}}}" : value.html).then(() => { setCopied(true); setCopyError(""); window.setTimeout(() => setCopied(false), 1500); }).catch(() => setCopyError("Copy failed. Select and copy the HTML manually.")); }}><Copy size={14}/>{copied ? "Copied" : kind === "footer" ? "Copy Liquid snippet" : "Copy HTML"}</button></div>
      <div className={styles.previewUser}><label>Preview user<select aria-label={`${title} preview user`} value={userId} onChange={event => { setUserId(event.target.value); setPreview(""); setShare(""); }}>{[{ id: "", email: "Random user" }, ...users].map(user => <option key={user.id} value={user.id}>{user.email}</option>)}</select></label><button className={styles.secondary} disabled={previewing} onClick={() => void renderPreview()}>{previewing ? "Rendering…" : "Preview & Test"}</button>{preview && <button className={styles.secondary} onClick={() => void sharePreview()}>Create preview link</button>}{kind === "footer" && <button className={styles.secondary} aria-pressed={plain} onClick={() => { setPlain(!plain); setCode(true); }}>Plain text footer</button>}</div>
      {previewUser && !code && <p className={styles.muted}>Previewing as {previewUser}</p>}
      {share && <p><a href={share} target="_blank" rel="noreferrer">Open shared preview (expires in 7 days)</a></p>}
      {previewError && <p role="alert" className={styles.error}>{previewError}</p>}
      {code ? plain ? <textarea spellCheck={false} aria-label={`${title} plain text`} readOnly={!editing} value={value.plainText ?? htmlToPlainText(value.html)} onChange={event => onChange({ ...value, plainText: event.target.value })}/> : <textarea spellCheck={false} aria-label={`${title} HTML`} readOnly={!editing} value={value.html} onChange={event => { onChange({ ...value, html: event.target.value }); setPreview(""); setShare(""); }}/>: preview ? <iframe title={`${title} preview`} sandbox="" srcDoc={preview}/> : <p>Select Preview to render the current content for the chosen user.</p>}

      {copyError && <p role="alert">{copyError}</p>}
    </div>}
  </section>;
}

function EditorSettings({ data, editing, patch }: { data: EmailPreferences["editor"]; editing: boolean; patch: (patch: Partial<EmailPreferences["editor"]>) => void }) {
  const scrollRef = useRef<HTMLDivElement | null>(null);
  const vf = (label: string, key: keyof typeof data, type = "text", options?: string[]) => <ValueField label={label} value={data[key] as string | number} editing={editing} type={type} options={options} onChange={value => patch({ [key]: type === "number" ? Number(value) : value })}/>;
  const color = (label: string, key: "canvasBg" | "contentBg" | "linkColor") => <ColorField label={label} value={data[key]} editing={editing} onChange={value => patch({ [key]: value })}/>;
  return <div className={`${styles.splitCard} ${styles.themeCard}`}><SectionNavigation sections={themeSections} scrollRef={scrollRef}/><div ref={scrollRef} className={styles.sectionContent}>
    <Heading editing={editing}>Email Global Style Settings</Heading><p>Global style settings allow you to add a default theme to your drag-and-drop email editor. These settings will be pre-configured for all future email campaigns, Canvases, and templates that use this editor. You can easily override these settings as needed. Learn more about <Learn href="https://www.braze.com/docs/user_guide/message_building_by_channel/email/drag_and_drop/dnd_email_style_settings/">global style settings</Learn>.</p><hr/>
    <section id="basic-styling"><h3>Basic Styling</h3><div className={styles.themeGrid}><div>{color("Email Background Color", "canvasBg")}{color("Default Link Color", "linkColor")}{color("Content Background Color", "contentBg")}{vf("Default Font Name", "fontFamily", "text", fonts)}</div><div className={styles.basicPreview} style={{ fontFamily: `${data.fontFamily},${data.fallbackFont},${data.genericFont}`, background: data.canvasBg }}><div style={{ background: data.contentBg }}>Default font and <span style={{ color: data.linkColor, textDecoration: "underline" }}>link color</span><br/><b>Bolded font</b><br/><i>Italicized font</i></div></div></div></section>
    <section id="title-styling"><h3>Title Styling</h3>{data.headers.map((theme, index) => <ThemeControls key={index} label={`Header ${index + 1}`} value={theme} editing={editing} simple onChange={value => patch({ headers: data.headers.map((header, i) => i === index ? value : header) })}><div style={textPreviewStyle(theme)}>{`Header ${index + 1}`}</div></ThemeControls>)}<h4>Block Styling for Headers</h4><div className={styles.paddingDiagram}>Top: {data.headers[0].paddingTop}<span>Left: {data.headers[0].paddingLeft}<b>Header</b>Right: {data.headers[0].paddingRight}</span>Bottom: {data.headers[0].paddingBottom}</div><div className={styles.paddingGrid}>{(["Top", "Right", "Bottom", "Left"] as const).map(side => <ValueField key={side} label={`Padding ${side}`} ariaLabel={`Headers Padding ${side}`} value={data.headers[0][`padding${side}`]} type="number" editing={editing} onChange={value => patch({ headers: data.headers.map(header => ({ ...header, [`padding${side}`]: Number(value) })) })}/>)}</div></section>
    <section id="paragraph-styling"><h3>Paragraph Styling</h3><ThemeControls label="Body Paragraph" value={data.paragraph} editing={editing} onChange={value => patch({ paragraph: value })}><div style={textPreviewStyle(data.paragraph)}>Body paragraph text and <span style={{ color: data.linkColor, textDecoration: "underline" }}>link color</span>. Curabitur pretium nisl non vehicula mattis.<p style={{ marginBottom: data.paragraph.spacing }}>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Proin metus magna, elementum ac scelerisque et, aliquam sit amet mi. Sed semper diam ac tortor commodo vehicula. Phasellus mi velit, sollicitudin nec rhoncus nec, ullamcorper in risus. Quisque nec orci in neque egestas porta. Vivamus dui urna, vestibulum et erat et, luctus imperdiet dolor. Ut mollis tortor sed sem suscipit, porttitor dignissim dolor aliquam. Vivamus at mi feugiat, dapibus metus in, volutpat neque. Sed egestas condimentum orci, ac finibus urna sodales ac.</p><p style={{ marginBottom: data.paragraph.spacing }}>Nullam turpis nisi, luctus in augue at, suscipit posuere mauris. In ut efficitur nunc. Proin orci odio, pretium vitae augue a, maximus porta tellus. Sed tincidunt quam orci. Cras elementum luctus turpis, eget tincidunt arcu luctus consequat. Etiam fringilla ultrices ipsum vel placerat. Maecenas odio nibh, commodo non mi eu, vehicula vulputate orci. Curabitur pretium nisl non vehicula mattis. Fusce a dui nec ex imperdiet pretium. Sed tempor nulla ac egestas vestibulum. Praesent venenatis gravida dolor quis fermentum. Vestibulum vestibulum eu urna eget elementum. Nullam rhoncus orci a diam euismod iaculis.</p></div></ThemeControls></section>
    <section id="list-styling"><h3>List Styling</h3><ThemeControls label="Body List" value={data.list} editing={editing} onChange={value => patch({ list: { ...data.list, ...value } })} extra={<><ValueField label="List Item Indent" type="number" value={data.list.indent} editing={editing} onChange={value => patch({ list: { ...data.list, indent: Number(value) } })}/><ValueField label="List Type" value={data.list.listType} options={["ul", "ol"]} editing={editing} onChange={value => patch({ list: { ...data.list, listType: value } })}/><ValueField label="List Style Type" value={data.list.marker} options={["default", "disc", "circle", "square", "decimal"]} editing={editing} onChange={value => patch({ list: { ...data.list, marker: value } })}/><ValueField label="Start List From (for numbered list)" value={data.list.start} editing={editing} type="number" min={1} onChange={value => patch({ list: { ...data.list, start: Number(value) } })}/></>}><div style={textPreviewStyle(data.list)}>Body list text and <span style={{ color: data.linkColor }}>link color</span>.{data.list.listType === "ol" ? <ol start={data.list.start}>{[1,2,3,4,5].map(item => <li key={item} style={{ marginBottom: data.list.spacing }}>{`Item ${item}.`}</li>)}</ol> : <ul style={{ paddingLeft: data.list.indent, listStyleType: data.list.marker === "default" ? undefined : data.list.marker }}>{[1,2,3,4,5].map(item => <li key={item} style={{ marginBottom: data.list.spacing }}>{`Item ${item}.`}{item === 3 && <ul><li>Nested item 1.</li><li>Nested item 2.</li></ul>}</li>)}</ul>}</div></ThemeControls></section>
    <section id="fallback-fonts"><h3>Fallback Fonts</h3><p>Fallback fonts will be used for the title, header, and body text when your default font choice is not available. <Learn href="https://www.braze.com/docs/user_guide/message_building_by_channel/email/drag_and_drop/dnd_email_style_settings#fallback-font"/>.</p><div className={styles.themeGrid}><div>{vf("Fallback font 1", "fallbackFont", "text", fonts)}<h4>Font family</h4><p>If your selected fallback fonts aren&apos;t available, the system will pick a font in this generic family</p><div className={styles.radios}>{["sans-serif", "serif"].map(value => <label key={value}><input type="radio" name="generic-font" disabled={!editing} checked={data.genericFont === value} onChange={() => patch({ genericFont: value })}/>{value === "serif" ? "Serif" : "Sans-serif"}</label>)}</div></div><div className={styles.previewBox} style={{ fontFamily: `${data.fallbackFont},${data.genericFont}` }}>Fallback font 1</div></div></section>
    <section id="button-styling"><h3>Button Styling</h3><ThemeControls label="Buttons" value={data.button} editing={editing} onChange={value => patch({ button: { ...data.button, ...value } })} extra={<><ValueField label="Border Weight" value={data.button.borderWidth} editing={editing} type="number" onChange={value => patch({ button: { ...data.button, borderWidth: Number(value) } })}/><ColorField label="Button Background Color" value={data.button.background} editing={editing} onChange={value => patch({ button: { ...data.button, background: value } })}/><ValueField label="Border Radius" value={data.button.radius} editing={editing} type="number" onChange={value => patch({ button: { ...data.button, radius: Number(value) } })}/><ColorField label="Border Color" value={data.button.borderColor} editing={editing} onChange={value => patch({ button: { ...data.button, borderColor: value } })}/><PaddingControls title="Button Padding" value={data.button.innerPadding} editing={editing} onChange={innerPadding => patch({ button: { ...data.button, innerPadding } })}/></>}><button className={styles.sampleButton} style={{ ...textPreviewStyle(data.button), padding: paddingCss(data.button.innerPadding), background: data.button.background, border: `${data.button.borderWidth}px solid ${data.button.borderColor}`, borderRadius: data.button.radius }}>Button</button></ThemeControls></section>
    <section id="icon-block-styling"><h3>Icon Block Styling</h3><div className={styles.themeGrid}><div><ValueField label="Font Size" value={data.icon.fontSize} type="number" editing={editing} onChange={value => patch({ icon: { ...data.icon, fontSize: Number(value) } })}/><ColorField label="Font Color" value={data.icon.color} editing={editing} onChange={color => patch({ icon: { ...data.icon, color } })}/>{([['Item Spacing','itemSpacing'],['Icon Height','height']] as const).map(([label,key]) => <ValueField key={key} label={label} value={data.icon[key]} editing={editing} type="number" onChange={value => patch({ icon: { ...data.icon, [key]: Number(value) } })}/>)}<ValueField label="Align" value={data.icon.align} options={["left","center","right"]} editing={editing} onChange={align => patch({ icon: { ...data.icon, align } })}/><PaddingControls title="Block Padding" value={{ top:data.icon.paddingTop,right:data.icon.paddingRight,bottom:data.icon.paddingBottom,left:data.icon.paddingLeft }} editing={editing} onChange={value => patch({ icon: { ...data.icon,paddingTop:value.top,paddingRight:value.right,paddingBottom:value.bottom,paddingLeft:value.left } })}/><PaddingControls title="Icon Padding" value={data.icon.padding} editing={editing} onChange={padding => patch({ icon: { ...data.icon, padding } })}/><h4>Mobile Styling for Icon Block</h4><ValueField label="Mobile Font Size" value={data.icon.mobileFontSize} editing={editing} type="number" onChange={value => patch({ icon: { ...data.icon, mobileFontSize: Number(value) } })}/><ValueField label="Mobile Text Align" value={data.icon.mobileAlign} options={["left", "center", "right"]} editing={editing} onChange={mobileAlign => patch({ icon: { ...data.icon, mobileAlign } })}/><PaddingControls title="Mobile Block Padding" value={data.icon.mobilePadding} editing={editing} onChange={mobilePadding => patch({ icon: { ...data.icon, mobilePadding } })}/></div><div><div className={styles.previewBox}><div style={{ ...textPreviewStyle(data.icon), display: "flex", justifyContent: data.icon.align === "left" ? "flex-start" : data.icon.align === "right" ? "flex-end" : "center", gap: data.icon.itemSpacing }}>{["#1871d8", "#00a3d7", "#e73e68"].map(color => <span key={color} style={{ padding: paddingCss(data.icon.padding), color }}><Circle size={data.icon.height} fill="currentColor" strokeWidth={0}/><span>Icon</span></span>)}</div></div><div className={styles.mobilePreview}><h4>Mobile Preview</h4><div style={{ fontSize: data.icon.mobileFontSize, textAlign: data.icon.mobileAlign as CSSProperties["textAlign"], padding: paddingCss(data.icon.mobilePadding), color: data.icon.color }}>● &nbsp; Icon text</div></div></div></div></section>
    <section id="email-template-width"><h3>Email Template Width</h3>{vf("Email template width (px)", "contentWidth", "number")}</section>
    <section id="content-block-width"><h3>Content Block Width</h3><p>These settings will be pre-configured for all future Content Blocks. Existing Content Blocks won&apos;t be updated.</p><div className={styles.themeGrid}><div className={styles.radios}>{[["full", "Full-width (100%)"], ["custom", "Custom width"]].map(([value,label]) => <label key={value}><input name="content-width" type="radio" disabled={!editing} checked={data.blockWidthMode === value} onChange={() => patch({ blockWidthMode: value })}/>{label}</label>)}{data.blockWidthMode === "custom" && vf("Content block width (px)", "blockWidth", "number")}</div><img className={styles.widthIllustration} src="/braze-email-preferences/content-block-width.png" alt="Content block width illustration"/></div></section>
  </div></div>;
}
function paddingCss(value: ThemePadding) { return `${value.top}px ${value.right}px ${value.bottom}px ${value.left}px`; }
function PaddingControls({ title, value, editing, onChange }: { title: string; value: ThemePadding; editing: boolean; onChange: (value: ThemePadding) => void }) {
  return <div><h4>{title}</h4><div className={styles.paddingGrid}>{(["top", "right", "bottom", "left"] as const).map(side => <ValueField key={side} label={`Padding ${side[0].toUpperCase()}${side.slice(1)}`} ariaLabel={`${title} ${side}`} value={value[side]} type="number" editing={editing} onChange={next => onChange({ ...value, [side]: Number(next) })}/>)}</div></div>;
}
function textPreviewStyle(value: TextTheme): CSSProperties { return { fontSize: value.fontSize, color: value.color, textAlign: value.align as CSSProperties["textAlign"], direction: value.direction as CSSProperties["direction"], fontWeight: value.weight, lineHeight: value.lineHeight, letterSpacing: value.letterSpacing, padding: `${value.paddingTop}px ${value.paddingRight}px ${value.paddingBottom}px ${value.paddingLeft}px` }; }
function ThemeControls({ label, value, editing, onChange, children, simple = false, extra }: { label: string; value: TextTheme; editing: boolean; onChange: (value: TextTheme) => void; children: ReactNode; simple?: boolean; extra?: ReactNode }) {
  const input = (title: string, key: keyof TextTheme, options?: string[]) => <ValueField label={title} ariaLabel={`${label} ${title}`} value={value[key]} type={typeof value[key] === "number" ? "number" : "text"} options={options} editing={editing} onChange={next => onChange({ ...value, [key]: typeof value[key] === "number" ? Number(next) : next })}/>;
  return <div className={styles.themeControls}>{simple && <h4>{label}</h4>}<div className={styles.themeGrid}><div>{input("Font Size", "fontSize")}<ColorField label={simple ? "Font Color" : label === "Body Paragraph" ? "Paragraph Font Color" : label === "Body List" ? "List Font Color" : label === "Buttons" ? "Button Font Color" : "Font Color"} ariaLabel={`${label} Font Color`} value={value.color} editing={editing} onChange={next => onChange({ ...value, color: next })}/>{!simple && label !== "Buttons" && <>{input("Font Weight", "weight", ["normal", "bold"])}{input("Line Height", "lineHeight", ["normal", "1", "1.2", "1.5", "1.8", "2"])}</>}{label !== "Buttons" && input("Align", "align", ["left", "center", "right"])}{label !== "Buttons" && input("Text Direction", "direction", ["ltr", "rtl"])}{!simple && label !== "Buttons" && <>{input("Letter Spacing", "letterSpacing")}{input(label === "Body List" ? "List Item Spacing" : "Paragraph Spacing", "spacing")}</>}{extra}</div><div className={`${styles.previewBox} ${label === "Buttons" ? styles.buttonPreview : ""}`}>{children}</div></div>{!simple && <><h4>Block Styling for {label}</h4><div className={styles.paddingDiagram} aria-label={`${label} block padding diagram`}>Top: {value.paddingTop}<span>Left: {value.paddingLeft} <b>{label}</b> Right: {value.paddingRight}</span>Bottom: {value.paddingBottom}</div><div className={styles.paddingGrid}>{(["Top", "Right", "Bottom", "Left"] as const).map(side => <span key={side}>{input(`Padding ${side}`, `padding${side}`)}</span>)}</div></>}</div>;
}

type TrackedAlias = { id: string; name: string; status: string; data: { url?: string; campaignName?: string } };
function LinkAliases({ editing, notify }: { editing: boolean; notify: (message: string) => void }) {
  const [rows, setRows] = useState<TrackedAlias[]>([]);
  const [query, setQuery] = useState("");
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState("All statuses");
  const [sort, setSort] = useState({ key: "name", descending: false });
  const [error, setError] = useState("");
  const [selected, setSelected] = useState<string[]>([]);
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  useEffect(() => { let active = true; void fetch("/api/resources/link-aliases").then(response => { if (!response.ok) throw new Error(); return response.json(); }).then(result => { if (active) setRows(result.data ?? []); }).catch(() => { if (active) setError("Tracked links could not be loaded."); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, []);
  const visible = rows.filter(row => (status === "All statuses" || row.status === status) && row.name.toLowerCase().includes(search.toLowerCase())).sort((a,b) => { const get = (row: TrackedAlias) => sort.key === "name" ? row.name : sort.key === "url" ? row.data.url ?? "" : sort.key === "campaign" ? row.data.campaignName ?? "" : row.status; return get(a).localeCompare(get(b)) * (sort.descending ? -1 : 1); });
  const deactivate = async () => {
    setSaving(true); setError("");
    try { const result = await Promise.all(selected.map(async id => { const response = await fetch("/api/resources/link-aliases", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id, status: "Inactive" }) }); if (!response.ok) throw new Error(); return id; })); setRows(current => current.map(row => result.includes(row.id) ? { ...row, status: "Inactive" } : row)); setSelected([]); notify("Link tracking disabled for selected aliases."); }
    catch { setError("Some aliases could not be updated. Reload the list before trying again."); }
    finally { setSaving(false); }
  };
  return <section className={`${styles.card} ${styles.aliasCard}`}><Heading editing={editing} large>Tracked Link Aliases</Heading><p>Email links tracked through Link Management will appear here. User profiles include their 100 most recently clicked links and are available to be used for segmentation. There is no limit on the total number of links tracked at the workspace level. <Learn href="https://www.braze.com/docs/user_guide/message_building_by_channel/email/templates/link_aliasing/">Learn more about Link Aliasing</Learn></p><p className={styles.aliasCount}>Showing <b>{rows.length}</b> Link Aliases tracked across this workspace.</p>
    <div className={styles.aliasFilters}><label>Status<select value={status} onChange={event => setStatus(event.target.value)}>{["All statuses", "Active", "Inactive"].map(item => <option key={item}>{item}</option>)}</select></label><form onSubmit={event => { event.preventDefault(); setSearch(query.trim()); }}><input aria-label="Search by alias" placeholder="Search by alias" value={query} onChange={event => setQuery(event.target.value)}/><button aria-label="Search aliases" type="submit"><Search size={20}/></button></form></div>
    {error && <p role="alert" className={styles.error}>{error}</p>}{selected.length > 0 && editing && <button className={styles.secondary} disabled={saving} onClick={() => void deactivate()}>Disable tracking ({selected.length})</button>}
    <div className={styles.tableWrap}><table><thead><tr>{editing && <th><input type="checkbox" aria-label="Select all aliases" checked={visible.length > 0 && visible.every(row => selected.includes(row.id))} onChange={event => setSelected(event.target.checked ? visible.map(row => row.id) : [])}/></th>}{[["name","Link Alias"],["url","Full Link"],["campaign","Associated Campaign or Canvas"],["status","Status"]].map(([key,label]) => <th key={key} aria-sort={sort.key === key ? sort.descending ? "descending" : "ascending" : "none"}><button title={key === "status" ? "Active aliases record clicks; inactive aliases do not record new clicks." : `Sort by ${label}`} onClick={() => setSort({ key, descending: sort.key === key ? !sort.descending : false })}>{label}{sort.key === key ? sort.descending ? <ArrowDown size={14}/> : <ArrowUp size={14}/> : <ArrowDownUp size={14} style={{ opacity:0.5 }}/>}</button></th>)}</tr></thead><tbody>{visible.map(row => <tr key={row.id}>{editing && <td><input type="checkbox" aria-label={`Select alias ${row.name}`} checked={selected.includes(row.id)} onChange={event => setSelected(current => event.target.checked ? [...current,row.id] : current.filter(id => id !== row.id))}/></td>}<td>{row.name}</td><td>{row.data.url}</td><td>{row.data.campaignName}</td><td>{row.status}</td></tr>)}{!visible.length && <tr><td className={styles.emptyTable} colSpan={editing ? 5 : 4}>{loading ? <p role="status">Loading tracked links…</p> : <><h3>{rows.length ? "No matching link aliases" : "You don't have any tracked links for Demo – bba yet"}</h3><p>{rows.length ? "Try another search or status filter." : <>Use the <b>Link Management</b> tab in the email editor to mark aliases for tracking.</>}</p></>}</td></tr>}</tbody></table></div>
  </section>;
}
function BotSettings({ value, editing, onChange }: { value: boolean; editing: boolean; onChange: (value: boolean) => void }) {
  return <section className={`${styles.card} ${styles.botCard}`}><Heading editing={editing}>Bot Filtering</Heading><p>These settings affect reports and analytics in this workspace</p><hr/><div className={styles.botGrid}><div><p>Braze detects <Learn href="https://www.braze.com/unlisted_docs/bot_filtering">bot activity</Learn> by flagging user agents, IP addresses, or both as bots, security software, anti-spam systems, or other potentially harmful entities. If a setting is turned on and later turned off, Braze cannot restore previously removed bot activity to analytics.</p><Toggle label="Remove bot clicks" checked={value} disabled={!editing} onChange={onChange}/></div><aside><b>Braze metrics affected by bot clicks</b><ul>{["Total Click Rate", "Unique Click Rate", "Click-to-Open Rate", "Conversion Rate (if clicks campaign is selected as the conversion event)", "Heatmap"].map(item => <li key={item}>{item}</li>)}<li>Certain <Learn href="https://www.braze.com/unlisted_docs/bot_filtering/#metrics-affected-by-bot-clicks">segment filters</Learn></li></ul></aside></div></section>;
}
function IpWarming() {
  const pathname = usePathname(); const router = useRouter(); const params = useSearchParams();
  const creating = pathname.includes("/ip_warming/new/");
  const setCreating = (value: boolean) => { const base = pathname.replace(/\/ip_warming(?:\/new)?\//, value ? "/ip_warming/new/" : "/ip_warming/"); router.push(`${base}?${params.toString() || "locale=en"}`); };
  const [moreInfo, setMoreInfo] = useState(false);
  if (!creating) return <section className={`${styles.card} ${styles.warmingCard}`}><h2 className={styles.largeHeading}>Automated IP Warming</h2><div className={styles.warmingEmpty}><img src="/braze-email-preferences/ip-warming.png" alt="IP warming"/><h3>You don&apos;t have any IP warming plans yet</h3><p>IP warming helps ensure deliverability by gradually<br/> increasing your sending volume for new IPs.</p><button className={styles.primary} onClick={() => setCreating(true)}>New IP warming plan</button></div></section>;
  return <div className={styles.warmingForm}><button className={styles.linkButton} onClick={() => setCreating(false)}><ArrowLeft size={18}/> Back</button><Heading editing={false} readOnly large>Automated IP Warming</Heading><div className={styles.steps}>{["Schedule", "Segments", "Messages", "Conversions", "Summary"].map((name,index) => <button key={name} disabled={index !== 0}><span>{index + 1}</span>{name}</button>)}</div><div className={styles.permissionNotice}><div><Info size={20}/><b>You need additional permissions to launch automated IP warming.</b><button className={styles.linkButton} aria-expanded={moreInfo} onClick={() => setMoreInfo(!moreInfo)}>More Info <ChevronDown size={16}/></button></div>{moreInfo && <div><section><b>Permissions needed:</b><ul>{["View Campaigns", "Edit Campaigns", "Approve Deny Campaigns", "Launch Campaigns"].map(permission => <li key={permission}>{permission}</li>)}</ul></section></div>}</div><section className={styles.card}><h2>Plan name</h2><p>Add a unique identifier for your IP warming plan.</p><ValueField label="Plan name" value="" editing={false} onChange={() => {}}/></section><section className={styles.card}><h2>Schedule</h2><p>Generate a schedule unique to your needs, so you can gradually increase your send volume.</p><details className={styles.helpPopover}><summary>Need help</summary><p>Choose a verified From address and IP pool, then build a schedule based on your sending history. Launching requires campaign edit, approval, and launch permissions.</p><Learn href="https://www.braze.com/docs/user_guide/message_building_by_channel/email/email_warming/automated_ip_warming/"/></details><div className={styles.sendingInformation}><h3>Sending information</h3><div>{["From address", "IP pool", "IP addresses in pool"].map((label, index) => <ValueField key={label} label={label} value={index === 0 ? "Select from address" : "—"} editing={false} onChange={() => {}}/>)}</div></div></section><div className={styles.warmingFooter}><button disabled className={styles.primary}>Next: Segments <ArrowRight size={16}/></button><button disabled className={styles.secondary}>Save as draft</button></div></div>;
}
